mapper.select:
SELECT u.mobile as mobile
FROM b_openid_share as bos
INNER JOIN b_openid as bo ON bos.share_openid_id = bo.openid_id
LEFT JOIN b_user as u ON bo.user_id = u.user_id
WHERE (
bos.user_id IN

    #{id}

AND bos.flag = 1
AND bo.app_id = #{appid}
)

select bu.user_id,bu.name,bu.realname,bu.mobile,bu.status,bo.name organizationName,bu.tenant_id from b_user bu, b_organization bo, r_user_tenant rut where bu.flag = 1 and bo.flag = 1 and rut.flag = 1 and bu.user_id = rut.user_id and bo.organization_id = rut.organization_id
and bu.tenant_id = #{param.tenantId}
and bo.organization_id = #{param.organizationId}
and bu.name like CONCAT('%',#{param.name},'%')
and bu.realname like CONCAT('%',#{param.realname},'%')
and bu.mobile like CONCAT('%',#{param.mobile},'%')
and bu.status = #{param.status}

select bu.user_id,bu.name,bu.realname,bu.mobile,bu.status,bo.name organizationName from b_user bu, b_organization bo, r_user_tenant rut, b_role br, r_user_role rur where bu.flag = 1 and bo.flag = 1 and rut.flag = 1 and rur.flag = 1 and bu.user_id = rut.user_id and bo.organization_id = rut.organization_id and bu.user_id = rur.user_id and br.role_id = rur.role_id
and bu.tenant_id = #{param.tenantId} and br.tenant_id = #{param.tenantId}
and br.role_id = #{param.roleId}
and bu.name like CONCAT('%',#{param.name},'%')
and bu.realname like CONCAT('%',#{param.realname},'%')
and bu.mobile like CONCAT('%',#{param.mobile},'%')

select a.mobile
from b_user a
         join r_user_tenant b on b.flag = 1 and b.user_id = a.user_id
         join r_user_role c on c.flag = 1 and c.user_id = a.user_id
         join b_role d on d.flag = 1 and d.role_id = c.role_id
where a.flag = 1
    /*二级公司*/
  and b.organization_id = #{orgId}
    /*二级公司客服*/
  and d.code = 'sub_company_customer'
  and a.tenant_id = #{tenantId}

select bu.* from b_user bu,b_role br,r_user_role rrr where bu.flag = 1 and br.flag = 1 and rrr.flag = 1 and bu.user_id = rrr.user_id and br.role_id = rrr.role_id and br.code = 'applet_user'
and bu.tenant_id = #{tenantId}
and (bu.name like CONCAT('%',#{name},'%') or bu.realname like CONCAT('%',#{name},'%') or bu.mobile like CONCAT('%',#{name},'%') )

select bu.user_id, bu.realname, bu.mobile, bu.open_id, null email
from b_user bu

    join r_user_role rur on rur.flag = 1 and rur.user_id = bu.user_id
    join b_role br on br.flag = 1 and br.role_id = rur.role_id


    join r_user_tenant rut on rut.flag = 1 and rut.user_id = bu.user_id
    join b_organization bo on bo.flag = 1 and bo.organization_id = rut.organization_id

where bu.flag = 1 and bu.status = 0
  and bu.tenant_id = #{tenantId}

    and bu.user_id = #{userId}


    and br.code in

        #{roleCode}



    and bo.organization_id = #{organizationId}

group by bu.user_id, bu.realname, bu.mobile, bu.open_id
